#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <cctype>
#include <string>
#include <array>
using namespace std;

constexpr int MAX_NODES = 2000;
constexpr int GRID_LIMIT = 12;
constexpr int INF_DIST = 1000000000;

array<array<int, GRID_LIMIT>, GRID_LIMIT> distGrid;
array<array<int, GRID_LIMIT>, GRID_LIMIT> inputA;
array<array<int, GRID_LIMIT>, GRID_LIMIT> inputB;
array<vector<int>, MAX_NODES> adjacency;
array<array<vector<int>, GRID_LIMIT>, GRID_LIMIT> exitNodes;

const array<int, 4> dRow = {0, -1, 0, 1};
const array<int, 4> dCol = {1, 0, -1, 0};

struct BipartiteMatcher {
    int leftMatch[MAX_NODES];
    int rightMatch[MAX_NODES];
    bool visited[MAX_NODES];
    int totalMatches;

    int findMaxMatching(int leftSize, vector<int> adj[]) {
        totalMatches = 0;
        fill(leftMatch, leftMatch + leftSize, -1);
        fill(rightMatch, rightMatch + MAX_NODES, -1);
        for (int u = 0; u < leftSize; ++u) {
            fill(visited, visited + MAX_NODES, false);
            if (tryAugment(u, adj)) ++totalMatches;
        }
        return totalMatches;
    }

private:
    bool tryAugment(int u, vector<int> adj[]) {
        for (int v : adj[u]) {
            if (visited[v]) continue;
            visited[v] = true;
            if (rightMatch[v] == -1 || tryAugment(rightMatch[v], adj)) {
                leftMatch[u] = v;
                rightMatch[v] = u;
                return true;
            }
        }
        return false;
    }
};

void multiSourceBFS(int startR, int startC) {
    queue<pair<int, int>> q;
    for (int i = 0; i < GRID_LIMIT; ++i)
        fill(distGrid[i].begin(), distGrid[i].end(), -1);
    q.emplace(startR, startC);
    distGrid[startR][startC] = 0;
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (int i = 0; i < 4; ++i) {
            int nr = r + dRow[i], nc = c + dCol[i];
            if (nr >= 0 && nr < GRID_LIMIT && nc >= 0 && nc < GRID_LIMIT &&
                inputA[nr][nc] >= 0 && distGrid[nr][nc] == -1) {
                distGrid[nr][nc] = distGrid[r][c] + 1;
                q.emplace(nr, nc);
            }
        }
    }
}

void expandSearch(int startR, int startC, int count, int maxTime, int &nodeCounter) {
    array<array<int, GRID_LIMIT>, GRID_LIMIT> visited;
    queue<pair<int, int>> q;
    for (int i = 0; i < GRID_LIMIT; ++i)
        fill(visited[i].begin(), visited[i].end(), -1);
    q.emplace(startR, startC);
    visited[startR][startC] = 0;
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        int limit = min(maxTime, distGrid[r][c]);
        if (visited[r][c] > limit) continue;
        for (int exitId : exitNodes[r][c]) {
            for (int k = 0; k < count; ++k) {
                adjacency[nodeCounter + k].push_back(exitId);
            }
        }
        if (visited[r][c] == limit) continue;
        for (int i = 0; i < 4; ++i) {
            int nr = r + dRow[i], nc = c + dCol[i];
            if (nr >= 0 && nr < GRID_LIMIT && nc >= 0 && nc < GRID_LIMIT &&
                inputA[nr][nc] >= 0 && visited[nr][nc] == -1) {
                visited[nr][nc] = visited[r][c] + 1;
                q.emplace(nr, nc);
            }
        }
    }
    nodeCounter += count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, timeLimit;
    cin >> n >> timeLimit;

    for (int i = 0; i < GRID_LIMIT; ++i)
        fill(inputA[i].begin(), inputA[i].end(), -1),
        fill(inputB[i].begin(), inputB[i].end(), -1);

    int startR = -1, startC = -1;

    string dummy;
    for (int i = 1; i <= n; ++i) {
        getline(cin, dummy);
        for (int j = 1; j <= n; ++j) {
            char c = cin.get();
            if (isdigit(c)) inputA[i][j] = c - '0';
            if (c == 'Z') { startR = i; startC = j; }
        }
    }
    cin.ignore();

    multiSourceBFS(startR, startC);

    for (int i = 1; i <= n; ++i) {
        getline(cin, dummy);
        for (int j = 1; j <= n; ++j) {
            char c = cin.get();
            if (isdigit(c)) inputB[i][j] = c - '0';
            for (int k = 0; k < inputB[i][j]; ++k) {
                exitNodes[i][j].push_back((int)exitNodes[i][j].size());
            }
        }
    }
    cin.ignore();

    for (int i = 0; i < GRID_LIMIT; ++i)
        for (int j = 0; j < GRID_LIMIT; ++j)
            if (distGrid[i][j] == -1) distGrid[i][j] = INF_DIST;

    int nodeCount = 0;
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (inputA[i][j] > 0)
                expandSearch(i, j, inputA[i][j], timeLimit, nodeCount);

    BipartiteMatcher solver;
    cout << solver.findMaxMatching(nodeCount, adjacency.data()) << '\n';
}
